impl<C> RequestBuilder<(), C> {
    /// Builds a [`Request`].
    pub fn build(self) -> Request {
        Request {
            index: self.index,
            expand_wildcards: self.expand_wildcards,
            health: self.health,
            include_unloaded_segments: self.include_unloaded_segments,
            pri: self.pri,
            master_timeout: self.master_timeout,
            h: self.h,
            s: self.s,
            error_trace: self.error_trace,
            filter_path: self.filter_path,
            human: self.human,
            pretty: self.pretty,
        }
    }
}

impl<C> crate::typed::builder::Build for RequestBuilder<(), C> {
    type Output = Request;

    fn build(self) -> Request {
        Self::build(self)
    }
}

impl RequestBuilder<(), &crate::Elasticsearch> {
    /// Sends the request.
    pub async fn send(self) -> std::result::Result<Response, crate::Error> {
        let client = self.bound_client;
        self.build().send(client).await
    }
}

impl Request {
    /// HTTP method and path of the request, using the most specific URL for the path parameters that are set.
    fn url(&self) -> (crate::http::Method, String) {
        if let Some(index) = &self.index {
            return (
                crate::http::Method::Get,
                format!("/_cat/indices/{}", crate::typed::support::path_part(index)),
            );
        }
        (crate::http::Method::Get, "/_cat/indices".to_string())
    }

    /// HTTP method of the request.
    pub fn method(&self) -> crate::http::Method {
        self.url().0
    }

    /// Path of the request, with path parameters percent-encoded.
    pub fn path(&self) -> String {
        self.url().1
    }

    /// Query string parameters of the request.
    pub fn query(&self) -> Vec<(&'static str, String)> {
        let mut query = Vec::new();
        if let Some(value) = &self.expand_wildcards {
            query.push((
                "expand_wildcards",
                crate::typed::support::query_value(value),
            ));
        }
        if let Some(value) = &self.health {
            query.push(("health", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.include_unloaded_segments {
            query.push((
                "include_unloaded_segments",
                crate::typed::support::query_value(value),
            ));
        }
        if let Some(value) = &self.pri {
            query.push(("pri", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.master_timeout {
            query.push(("master_timeout", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.h {
            query.push(("h", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.s {
            query.push(("s", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.error_trace {
            query.push(("error_trace", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.filter_path {
            query.push(("filter_path", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.human {
            query.push(("human", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.pretty {
            query.push(("pretty", crate::typed::support::query_value(value)));
        }
        query
    }

    pub(crate) async fn send(
        self,
        client: &crate::Elasticsearch,
    ) -> std::result::Result<Response, crate::Error> {
        use crate::http::{headers::HeaderMap, request::JsonBody};
        let (method, path) = self.url();
        let query = self.query();
        let response = client
            .transport()
            .send(
                method,
                &path,
                HeaderMap::new(),
                Some(&query),
                None::<JsonBody<()>>,
                None,
            )
            .await?
            .error_for_status_code()?;
        response.json().await
    }
}

